import{_ as e,c as i,o as n,ae as s}from"./chunks/framework.BlRNOFgT.js";const p=JSON.parse('{"title":"Latihan Soal: WebAssembly","description":"","frontmatter":{},"headers":[],"relativePath":"WBD/assambly.md","filePath":"WBD/assambly.md"}'),t={name:"WBD/assambly.md"};function l(r,a,m,u,d,o){return n(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="latihan-soal-webassembly" tabindex="-1">Latihan Soal: WebAssembly <a class="header-anchor" href="#latihan-soal-webassembly" aria-label="Permalink to &quot;Latihan Soal: WebAssembly&quot;">​</a></h1><h2 id="bagian-1-karakteristik-fundamental-arsitektur" tabindex="-1">Bagian 1: Karakteristik Fundamental &amp; Arsitektur <a class="header-anchor" href="#bagian-1-karakteristik-fundamental-arsitektur" aria-label="Permalink to &quot;Bagian 1: Karakteristik Fundamental &amp; Arsitektur&quot;">​</a></h2><p><strong>1. Manakah dari pernyataan berikut yang secara akurat mendeskripsikan sifat teknis WebAssembly (WASM)?</strong></p><ul><li>A. Merupakan format instruksi biner tingkat rendah (low-level).</li><li>B. Dirancang untuk menggantikan JavaScript sepenuhnya dalam pengembangan web modern.</li><li>C. Memiliki eksekusi yang sandboxed untuk keamanan.</li><li>D. Merupakan bahasa pemrograman tingkat tinggi yang diketik secara statis (statically typed).</li><li>E. Format instruksinya bersifat platform-independent.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, E</strong></p><p><strong>Penjelasan:</strong> Opsi B salah karena WASM dirancang untuk berjalan bersampingan dengan JavaScript (Web compatibility), bukan menggantikannya. Opsi D salah karena WASM adalah format instruksi biner (hasil kompilasi), bukan bahasa sumber tingkat tinggi seperti C++ atau Rust.</p></details><hr><p><strong>2. WebAssembly Virtual Machine (VM) mengemulasikan CPU riil dengan arsitektur tertentu. Komponen atau karakteristik mana yang benar terkait arsitektur VM ini?</strong></p><ul><li>A. Menggunakan arsitektur berbasis register (Register-based VM) untuk efisiensi tinggi.</li><li>B. Menggunakan struktur data Stack untuk operasi.</li><li>C. Memiliki Instruction Pointer yang menunjuk ke instruksi berikutnya.</li><li>D. Memiliki Stack Pointer yang menunjuk ke bagian bawah stack.</li><li>E. Menerjemahkan modul WASM menjadi kode mesin spesifik perangkat keras (seperti x86 atau ARM).</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, E</strong></p><p><strong>Penjelasan:</strong> Opsi A salah fatal karena WASM VM adalah Stack-based, bukan Register-based. Opsi D salah karena Stack Pointer menunjuk ke bagian atas (top) dari stack, bukan bawah.</p></details><hr><p><strong>3. Dalam konteks pengembangan aplikasi menggunakan bahasa seperti C++ atau Rust untuk WebAssembly, manakah tahapan yang valid?</strong></p><ul><li>A. Kode sumber dikompilasi langsung oleh browser menjadi file <code>.wasm</code>.</li><li>B. Kode sumber dikompilasi menggunakan compiler khusus bahasa tersebut menjadi modul WASM.</li><li>C. Modul WASM dieksekusi oleh WASM Virtual Machine.</li><li>D. WASM VM menghasilkan kode mesin spesifik target hardware (seperti ARM atau x86).</li><li>E. Kode sumber C++ diterjemahkan menjadi JavaScript sebelum dijalankan di VM.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, D</strong></p><p><strong>Penjelasan:</strong> Opsi A salah karena kompilasi ke <code>.wasm</code> terjadi di sisi pengembang (development time), bukan di dalam browser. Opsi E salah karena tujuan WASM adalah menghindari overhead JavaScript untuk tugas berat; C++ dikompilasi ke biner WASM, bukan JS.</p></details><hr><p><strong>4. Terdapat beberapa ekstensi file yang diasosiasikan dengan ekosistem WebAssembly. Manakah pasangan ekstensi dan deskripsi yang benar?</strong></p><ul><li>A. <code>.wasm</code>: Format biner yang telah terkompilasi dan siap dieksekusi.</li><li>B. <code>.wat</code>: Format teks yang dapat dibaca manusia (human readable).</li><li>C. <code>.wast</code>: Format biner terkompresi untuk distribusi jaringan.</li><li>D. <code>.wat</code>: Digunakan sebagai representasi source code dari format biner.</li><li>E. <code>.wast</code>: Format teks yang berguna untuk pengujian (testing) atau memuat multiple modules.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, D, E</strong></p><p><strong>Penjelasan:</strong> Opsi C adalah pengecoh. <code>.wast</code> juga merupakan format teks (bukan biner) yang sering digunakan untuk test suites atau mendefinisikan beberapa modul dalam satu file.</p></details><hr><p><strong>5. Bagaimana karakteristik model memori linier yang digunakan oleh WebAssembly?</strong></p><ul><li>A. Merupakan array byte yang kontigu (berurutan).</li><li>B. Ukurannya tetap (fixed) dan tidak dapat diubah setelah inisialisasi.</li><li>C. Dapat diakses oleh JavaScript sebagai <code>ArrayBuffer</code>.</li><li>D. Memori dibagi menjadi segmen heap dan stack yang dikelola otomatis oleh Garbage Collector browser.</li><li>E. Bersifat resizable (dapat diubah ukurannya).</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, E</strong></p><p><strong>Penjelasan:</strong> Opsi B salah karena memori WASM bersifat resizable. Opsi D salah karena WASM (dalam bentuk aslinya/MVP) menggunakan model memori linier manual (seperti C/C++), bukan garbage collected heap seperti Java/JS.</p></details><hr><h2 id="bagian-2-interaksi-dengan-javascript-web-api" tabindex="-1">Bagian 2: Interaksi dengan JavaScript &amp; Web API <a class="header-anchor" href="#bagian-2-interaksi-dengan-javascript-web-api" aria-label="Permalink to &quot;Bagian 2: Interaksi dengan JavaScript &amp; Web API&quot;">​</a></h2><p><strong>6. Tinjau kemampuan WebAssembly dalam berinteraksi dengan lingkungan browser. Manakah pernyataan yang teknisnya benar?</strong></p><ul><li>A. WebAssembly dapat memanipulasi elemen DOM secara langsung tanpa perantara.</li><li>B. WebAssembly membutuhkan JavaScript &quot;glue code&quot; untuk mengakses Web API.</li><li>C. WebAssembly hanya dapat mengirimkan tipe data primitif (integer/float) ke JavaScript.</li><li>D. Fungsi WebAssembly dapat memanggil <code>document.getElementById</code> secara native.</li><li>E. JavaScript bertugas memperbarui DOM berdasarkan hasil komputasi WASM.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, E</strong></p><p><strong>Penjelasan:</strong> Opsi A dan D adalah kesalahan konsep umum. WASM saat ini tidak bisa mengakses DOM atau Web API secara langsung; ia harus memanggil fungsi JavaScript (yang diimpor) untuk melakukan hal tersebut.</p></details><hr><p><strong>7. Dalam proses porting kode C/C++ ke WebAssembly, apa fungsi spesifik dari toolchain Emscripten?</strong></p><ul><li>A. Mengubah kode C/C++ menjadi kode Python untuk backend.</li><li>B. Menggunakan Clang+LLVM untuk kompilasi kode sumber.</li><li>C. Menghasilkan kode &quot;glue&quot; JavaScript dan HTML yang diperlukan.</li><li>D. Mengubah hasil kompilasi LLVM menjadi biner Wasm.</li><li>E. Menggantikan peran browser dalam merender grafik 3D.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, D</strong></p><p><strong>Penjelasan:</strong> Opsi A tidak relevan. Opsi E salah karena Emscripten adalah compiler toolchain, bukan rendering engine. Emscripten memfasilitasi pembuatan biner wasm DAN kode perekat JS agar wasm bisa berjalan di browser.</p></details><hr><p><strong>8. Berdasarkan studi kasus implementasi (misalnya pada Figma), apa keuntungan performa WebAssembly dibandingkan asm.js atau JavaScript murni?</strong></p><ul><li>A. Ukuran unduhan (download size) yang jauh lebih kecil.</li><li>B. Waktu muat (load time) yang lebih cepat.</li><li>C. Menghilangkan kebutuhan akan parsing kode karena sudah dalam bentuk biner.</li><li>D. Tidak memerlukan proses gzip atau brotli karena sudah terkompresi.</li><li>E. Eksekusi kode mendekati kecepatan native.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, E</strong></p><p><strong>Penjelasan:</strong> Opsi C kurang tepat karena browser masih perlu melakukan validasi/kompilasi awal pada biner wasm, meskipun jauh lebih cepat daripada parsing teks JS. Opsi D salah fatal; data menunjukkan bahwa kompresi gzip/brotli tetap diterapkan dan mengurangi ukuran file wasm secara signifikan.</p></details><hr><p><strong>9. Perhatikan potongan logika pemuatan modul berikut (konseptual):</strong></p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fetch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;module.wasm&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) → </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arrayBuffer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() → </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">instantiate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div><p><strong>Apa implikasi dari urutan proses ini?</strong></p><ul><li>A. <code>fetch</code> digunakan untuk mengambil file biner dari server.</li><li>B. <code>response.arrayBuffer()</code> mengubah respons menjadi representasi byte mentah di memori.</li><li>C. <code>WebAssembly.instantiate</code> mengompilasi dan membuat instans modul secara sinkron (memblokir main thread).</li><li>D. Objek <code>results.instance</code> berisi fungsi-fungsi yang diekspor (exports) oleh modul WASM.</li><li>E. Proses ini membuktikan bahwa WASM tidak memerlukan JavaScript sama sekali untuk berjalan.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, D</strong></p><p><strong>Penjelasan:</strong> Opsi C salah karena <code>instantiate</code> (terutama yang menerima buffer/promise) berjalan secara asynchronous (mengembalikan Promise). Opsi E salah karena kode di atas jelas-jelas adalah kode JavaScript yang diperlukan untuk memuat WASM.</p></details><hr><p><strong>10. Aplikasi jenis apa yang paling diuntungkan dengan migrasi ke WebAssembly berdasarkan kapabilitasnya menangani tugas berat?</strong></p><ul><li>A. Aplikasi CRUD sederhana (Create, Read, Update, Delete).</li><li>B. Editor grafis vektor (seperti Figma).</li><li>C. Rendering peta 3D (seperti Google Earth).</li><li>D. Formulir pendaftaran pengguna statis.</li><li>E. Simulasi ilmiah dan video editing.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, E</strong></p><p><strong>Penjelasan:</strong> Opsi A dan D adalah pengecoh. WASM didesain untuk performance-critical applications. Menggunakan WASM untuk formulir sederhana adalah overkill dan tidak efisien dibandingkan JS biasa.</p></details><hr><h2 id="bagian-3-modularitas-bahasa-sumber" tabindex="-1">Bagian 3: Modularitas &amp; Bahasa Sumber <a class="header-anchor" href="#bagian-3-modularitas-bahasa-sumber" aria-label="Permalink to &quot;Bagian 3: Modularitas &amp; Bahasa Sumber&quot;">​</a></h2><p><strong>11. WebAssembly didesain berbasis modul (module-based). Apa arti teknis dari pernyataan ini?</strong></p><ul><li>A. Modul adalah unit fungsionalitas yang mandiri (self-contained).</li><li>B. Satu aplikasi hanya boleh memuat satu modul WASM.</li><li>C. Modul dapat mengekspor fungsi untuk digunakan oleh modul lain atau JavaScript.</li><li>D. Modul dapat mengimpor fungsi dari host environment (JavaScript).</li><li>E. Modul berisi logika inti yang dapat digunakan kembali (reusable).</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, D, E</strong></p><p><strong>Penjelasan:</strong> Opsi B salah. Slide menyebutkan bahwa pengembang dapat memuat dan mengeksekusi multiple WASM modules dalam satu aplikasi (composable).</p></details><hr><p><strong>12. Manakah fakta sejarah dan perkembangan yang benar terkait WebAssembly?</strong></p><ul><li>A. Diumumkan sebagai proyek W3C pada tahun 2015.</li><li>B. Dukungan stabil di browser utama (Chrome, Firefox, Edge, Safari) baru tercapai pada tahun 2024.</li><li>C. JavaScript (asm.js) muncul setelah WebAssembly sebagai penyempurnaan.</li><li>D. Sejak 2020+, cakupan WASM meluas ke luar browser (Server-side, IoT).</li><li>E. Awalnya hanya didukung oleh Google Chrome.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, D</strong></p><p><strong>Penjelasan:</strong> Opsi B salah, rilis stabil di browser utama terjadi pada 2017. Opsi C terbalik; asm.js adalah pendahulu yang mencoba mengoptimalkan JS sebelum WASM ada. Opsi E salah karena ini adalah proyek kolaboratif W3C sejak awal.</p></details><hr><p><strong>13. Bahasa pemrograman apa saja yang disebutkan secara eksplisit memiliki dukungan compiler atau alur kerja untuk menjadi modul WebAssembly?</strong></p><ul><li>A. C &amp; C++</li><li>B. Rust</li><li>C. Golang</li><li>D. HTML</li><li>E. SQL</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, C</strong></p><p><strong>Penjelasan:</strong> Opsi D dan E adalah pengecoh. HTML adalah bahasa markup dan SQL adalah bahasa query database; keduanya bukan bahasa pemrograman sistem yang dikompilasi menjadi instruksi biner WASM dalam konteks arsitektur standar.</p></details><hr><h2 id="bagian-4-implementasi-praktis" tabindex="-1">Bagian 4: Implementasi Praktis <a class="header-anchor" href="#bagian-4-implementasi-praktis" aria-label="Permalink to &quot;Bagian 4: Implementasi Praktis&quot;">​</a></h2><p><strong>14. Jika Anda memiliki modul WASM yang mengekspor fungsi <code>add(a, b)</code>, dan Anda ingin menampilkan hasilnya di halaman web. Langkah mana yang benar secara teknis?</strong></p><ul><li>A. Panggil <code>wasmModule.exports.add(5, 10)</code> di dalam JavaScript.</li><li>B. Fungsi <code>add</code> akan langsung mengubah teks di dalam tag HTML <code>&lt;p&gt;</code> tanpa bantuan JS.</li><li>C. Gunakan JavaScript untuk menangkap nilai kembalian fungsi <code>add</code>.</li><li>D. Gunakan <code>document.getElementById(...).innerText</code> di dalam kode JavaScript untuk menampilkan hasil.</li><li>E. Fungsi <code>add</code> dieksekusi di server, bukan di browser.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, D</strong></p><p><strong>Penjelasan:</strong> Opsi B salah karena WASM tidak punya akses DOM. Opsi E salah karena konteks standar WASM web adalah client-side execution (kecuali dibahas konteks server-side spesifik, tapi di sini konteksnya adalah interaksi browser).</p></details><hr><p><strong>15. Apa kelemahan mendasar JavaScript yang memicu kebutuhan akan WebAssembly untuk komputasi berat?</strong></p><ul><li>A. JavaScript tidak didukung secara native oleh browser.</li><li>B. JavaScript tidak ideal untuk tugas intensif seperti scientific simulations atau gaming.</li><li>C. JavaScript adalah satu-satunya bahasa yang didukung native browser (sebelum WASM), membatasi opsi bahasa pengembang.</li><li>D. JavaScript tidak memiliki manajemen memori garbage collection.</li><li>E. Kecepatan eksekusi JavaScript sulit mencapai near-native speed secara konsisten untuk beban kerja berat.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, E</strong></p><p><strong>Penjelasan:</strong> Opsi A jelas salah. Opsi D salah karena JS justru memiliki Garbage Collection, yang kadang menjadi penyebab ketidakkonsistenan performa (jeda GC) dibandingkan manajemen memori manual di WASM (via bahasa asal seperti C++).</p></details><hr><p><strong>16. Mengapa Emscripten perlu menghasilkan &quot;JS Glue Code&quot; selain file <code>.wasm</code>?</strong></p><ul><li>A. Karena file <code>.wasm</code> tidak bisa diunduh oleh browser tanpa JS.</li><li>B. Untuk menyediakan jembatan (interface) agar WASM bisa memanggil Web API.</li><li>C. Untuk memuat (loading) dan menginisialisasi modul WASM.</li><li>D. Untuk mengubah kode biner WASM kembali menjadi C++ saat runtime.</li><li>E. Untuk mengalokasikan memori awal yang dibutuhkan WASM.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, E</strong></p><p><strong>Penjelasan:</strong> Opsi D salah besar; itu disebut dekompilasi dan bukan tujuan glue code. Glue code krusial untuk setup lingkungan (imports, memory allocation) yang memungkinkan biner WASM berinteraksi dengan dunia luar.</p></details><hr><p><strong>17. Dimana saja kode WebAssembly dapat dijalankan sesuai perkembangannya?</strong></p><ul><li>A. Di dalam browser web (Client-side).</li><li>B. Di sisi server (Server-side).</li><li>C. Pada perangkat IoT.</li><li>D. Di dalam Kernel Sistem Operasi Windows secara langsung sebagai driver.</li><li>E. Menggunakan runtime seperti <code>wasmtime</code>.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, C, E</strong></p><p><strong>Penjelasan:</strong> Opsi D adalah pengecoh yang terlalu spesifik dan tidak disebutkan dalam materi. Materi secara eksplisit menyebutkan Browser, Server-side, IoT, dan wasmtime.</p></details><hr><h2 id="bagian-5-technical-deep-dive" tabindex="-1">Bagian 5: Technical Deep Dive <a class="header-anchor" href="#bagian-5-technical-deep-dive" aria-label="Permalink to &quot;Bagian 5: Technical Deep Dive&quot;">​</a></h2><p><strong>18. Dalam arsitektur Stack Based VM milik WASM, manakah komponen kunci yang terlibat dalam eksekusi instruksi aritmatika?</strong></p><ul><li>A. Heap Pointer.</li><li>B. Stack Data Structure.</li><li>C. Instructions (Instruksi operasi).</li><li>D. Instruction Pointer.</li><li>E. GPU Registers.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, D</strong></p><p><strong>Penjelasan:</strong> Opsi A dan E adalah pengecoh istilah teknis. &quot;Heap Pointer&quot; bukan salah satu dari 4 objek kunci VM yang disebutkan (adanya Stack Pointer), dan GPU Registers tidak relevan dengan definisi dasar Stack Based VM untuk CPU emulation ini.</p></details><hr><p><strong>19. Berdasarkan grafik perbandingan Download Size antara asm.js dan WebAssembly:</strong></p><ul><li>A. Ukuran Uncompressed WebAssembly jauh lebih besar daripada asm.js.</li><li>B. Ukuran Uncompressed WebAssembly lebih kecil daripada asm.js (sekitar 6MB vs 9MB+).</li><li>C. Setelah kompresi Gzip, ukuran keduanya menjadi identik.</li><li>D. WebAssembly secara konsisten memiliki ukuran lebih kecil baik sebelum maupun sesudah kompresi (Gzip/Brotli).</li><li>E. asm.js lebih efisien dalam hal ukuran dokumen kosong (Empty document).</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, D</strong></p><p><strong>Penjelasan:</strong> Opsi A salah, data menunjukkan WASM lebih kecil. Opsi C salah, grafik menunjukkan perbedaan tetap ada meski mengecil. Opsi E salah, grafik Load Time/Size menunjukkan keunggulan WASM.</p></details><hr><p><strong>20. Fitur keamanan apa yang menjadi karakteristik utama WebAssembly?</strong></p><ul><li>A. Akses penuh ke file system pengguna (Full file system access).</li><li>B. Eksekusi yang terisolasi (Sandboxed execution).</li><li>C. Memori yang tidak dapat dibaca oleh host environment.</li><li>D. Validasi tipe data pada perbatasan modul (Module boundary).</li><li>E. Enkripsi otomatis seluruh kode sumber.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B</strong></p><p><strong>Penjelasan:</strong> Opsi A adalah risiko keamanan, bukan fitur, dan WASM dibatasi (sandboxed). Opsi C salah karena memori dibagi (shared) sebagai <code>ArrayBuffer</code>. Opsi E tidak disebutkan dan bukan standar; biner WASM tidak terenkripsi, hanya terkompilasi. Catatan: Meskipun validasi tipe terjadi, poin paling eksplisit di slide definisi adalah &quot;Secure and sandboxed execution&quot;.</p></details>',87)])])}const g=e(t,[["render",l]]);export{p as __pageData,g as default};
